            'id': r['job_id'],
            'scraped': scraped,
            'http_status': page.get('http_status'),
            'title_tag': (page.get('title_tag') or '')[:100],
            'h1': (page.get('h1') or '')[:100],
            'visible_text_snippet': (page.get('visible_text') or '')[:300]
