    matched_titles = [profile_titles[i] for i,wset in enumerate(profile_title_sets) if wset <= title_words(rt)]

    ls = collect_location_strings(row)

    print(f'\\n{jid}:')
    print(f'  resolved_company={rc!r} -> passes={company_passes} (first match: {matched_companies[:2]})')
    print(f'  resolved_title={rt!r} -> passes={title_passes} (matched: {matched_titles[:5]})')
    print(f'  location_strings={ls}')
