"""Collect location strings and tag remote hints; drop jobs provably outside the profile country."""

from __future__ import annotations

import re
import time

from v2.shared.observability.sli_observe import error_out, passed, reject, sli_observe
from v2.shared.patterns.logging import get_logger, log_event
from v2.shared.patterns.worker_runtime import ExecutionResult

MODULE_NAME = "job_matcher__normalise_location"
MODULE_TYPE = "filter"
REJECTION_REASONS = {"LOCATION_NOT_IN_PROFILE"}
ERROR_REASONS = {"PROCESSING_ERROR"}
WARNING_REASONS: set[str] = set()

_PLACEHOLDER_RE = re.compile(r"^\d+\s+location", re.IGNORECASE)
_REMOTE_RE = re.compile(r"\b(remote|home.based|work from home|wfh|home based)\b", re.IGNORECASE)
_NON_LATIN_RE = re.compile(r"[　-鿿가-힯Ѐ-ӿ]")  # CJK / Korean / Cyrillic

# Explicit non-UK country names that may appear in scraped location strings.
_OUTSIDE_UK_RE = re.compile(
    r"\b(united states|united states of america|canada|australia|new zealand|usa|u\.s\.a\.)\b",
    re.IGNORECASE,
)

# Matches "Location: <text>" in page body; captures up to 120 chars.
_LOC_IN_TEXT_RE = re.compile(r"\bLocation[:\s]+([^\n]{2,120})", re.IGNORECASE)

# Field-name markers that end a location clause in job-ad text.
_LOC_FIELD_END_RE = re.compile(
    r"\s+(?:Contract|Salary|Company|Job\s*Type|Posted|Apply|Working\s*Hours|Hours|Benefits|Ref)\s*:",
    re.IGNORECASE,
)


def _collect_location_strings(row: dict) -> list[str]:
    """All location text for metadata / downstream use."""
    strings: list[str] = []
    page = row.get("page") or {}
    sj = page.get("structured_job") or {}

    for loc in sj.get("locations") or []:
        if loc and str(loc).strip():
            strings.append(str(loc).strip())

    sj_loc = (sj.get("location") or "").strip()
    if sj_loc:
        strings.append(sj_loc)
    for loc in sj.get("additional_locations") or []:
        if loc and str(loc).strip():
            strings.append(str(loc).strip())

    scraped = (row.get("location") or "").strip()
    if scraped and not _PLACEHOLDER_RE.match(scraped):
        strings.append(scraped)

    # When a scraper incorrectly appends a non-UK country to a UK city (e.g.
    # "Birmingham, AL, United States"), surface the city portion alone so the
    # LLM can still match the UK city name against profile locations.
    for s in list(strings):
        if _OUTSIDE_UK_RE.search(s):
            city = s.split(",")[0].strip()
            if city and city not in strings:
                strings.append(city)

    # Extract locations from page body text as a fallback when structured data
    # omits some locations (e.g. "Location: Bristol, Derby or Solihull" in text
    # but structured_job only lists Bristol and Derby).
    text = (page.get("text") or "").strip()
    if text:
        m = _LOC_IN_TEXT_RE.search(text[:600])
        if m:
            raw = _LOC_FIELD_END_RE.split(m.group(1))[0]
            for part in re.split(r",\s*|\s+or\s+", raw):
                part = part.strip()
                if 2 <= len(part) <= 50 and part not in strings:
                    strings.append(part)

    return strings
